from __monty_host__ import host_coroutines
import json
TRACE = []
def op(name):
    result = json.loads((yield exchange(json.dumps({'phase': name, 'trace': TRACE}))))
    TRACE.append([name, result])
    return result
async def body():
    try:
        await op('body')
    except ValueError as error:
        TRACE.append(['caught-in-body', str(error)])
        await op('recovery')
        try:
            raise TypeError('LATER')
        except TypeError:
            TRACE.append('recovered-later')
        return 'recovered'

async def entry():
    try:
        return await body()
    except ValueError as error:
        TRACE.append(['caught', str(error)])
        return 'caught'
value = entry()._native1()
json.dumps({'value': value, 'trace': TRACE})

